// Mesma classificacao conservadora do workflow legado de pos-consulta
// (node 'Classificar Resultado Evolution', producao): so 'sucesso' com
// key.id explicito confirma o envio. Qualquer outra coisa (rejeicao HTTP,
// timeout, resposta ambigua) NAO confirma -- a jornada fica 'finalizando',
// expira e sera reclamada no proximo ciclo (comportamento aceito e
// documentado, mesmo espirito do legado).
const resp = $json;
let confirmado = false, messageId = null, motivo = null;
if (resp && resp.success === true && resp.data && resp.data.key && resp.data.key.id) {
  confirmado = true;
  messageId = resp.data.key.id;
} else if (resp && resp.error !== undefined) {
  motivo = String(resp.error).slice(0, 300);
} else {
  motivo = 'resposta_sem_key_id_sem_erro_explicito';
}
return { json: { envio_confirmado: confirmado, message_id: messageId, motivo_evolution: motivo } };
